class MozSearchValue extends MozXULElement {
  static get observedAttributes() {
    return ["disabled"];
  }

  constructor() {
    super();

    this.addEventListener("keypress", event => {
      if (event.keyCode != KeyEvent.DOM_VK_RETURN) {
        return;
      }
      onEnterInSearchTerm(event);
    });
